using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using HarborValeGreybox.Racing;
using HarborValeGreybox.Garage;
using HarborValeGreybox.Driving;
namespace HarborValeGreybox.Workshop.Editor {
public static class WorkshopVerification {
 static List<string> lines=new List<string>();static void Check(bool yes,string name){lines.Add((yes?"PASS ":"FAIL ")+name);if(!yes)throw new Exception(name);}
 static void Reject(Action action,string name){bool rejected=false;try{action();}catch{rejected=true;}Check(rejected,name);}
 static TrialSession Finish(TrialDefinition d){var s=new TrialSession(d);s.Tick(4,Vector3.zero,Vector3.zero);s.Tick(90,Vector3.zero,Vector3.zero);foreach(var g in d.checkpoints)s.Tick(.02f,g.Position-g.Forward,g.Position+g.Forward);return s;}
 static void Purchase(RaceProgressStore store,string id){store.PurchaseWorkshop(Guid.NewGuid().ToString("N"),id,WorkshopCatalog.Load("car_finch").Find(id).price,out _);}
 public static void Run(){Directory.CreateDirectory("Verification/Workshop");try{
  Check(DocksideTrialDirector.SavePath.EndsWith("race-progress-v4.json")&&DocksideTrialDirector.PreviousSavePath.EndsWith("race-progress-v3.json")&&DocksideTrialDirector.SavePath!=DocksideTrialDirector.PreviousSavePath,"Production v4 path separate from read-only v3 legacy source");
  var finch=WorkshopCatalog.Load("car_finch");var legacy=JsonUtility.FromJson<GarageCatalog>(Resources.Load<TextAsset>("FinchGarageCatalog").text);
  foreach(string car in new[]{"car_finch","car_apex_test"}){var catalog=WorkshopCatalog.Load(car);Check(catalog.offers.Select(o=>o.id).Distinct().Count()==catalog.offers.Length,"Unique authored IDs "+car);foreach(var offer in catalog.offers){if(offer.apexOnly&&car=="car_finch"){Check(catalog.Requirement(new WorkshopBuild(),offer).Contains("Apex"),"Unsupported Finch twin clearly gated");continue;}var build=new WorkshopBuild();foreach(var part in catalog.MissingPath(build,offer))catalog.Apply(build,part);Check(catalog.Installed(build,offer),"Reachable staged offer "+car+" "+offer.id);var d=catalog.Resolve(build);Check(d.PeakKw()>0&&d.PeakKw()<catalog.car.maxPowerKw,"Valid authored net curve "+offer.id);}}
  Check(finch.Find("na_1").price==400&&finch.Find("gearbox_1").price==250&&finch.Find("induction_small_1").price==1900&&finch.Find("cooling_1").price==400,"Four frozen legacy prices preserved");
  Check(finch.Resolve(finch.FromLegacy(2,1,1)).torque.SequenceEqual(legacy.turboStreet.torque),"Legacy small turbo/street cooler curve exact");
  var sound=finch.FromLegacy(2,1,1);float before=finch.Resolve(sound).PeakKw();sound.sound="burble";sound.soundStage=2;Check(Mathf.Abs(finch.Resolve(sound).PeakKw()/before-.96f)<.0001f,"Stage2 burble costs exactly 4% once");Check(finch.Resolve(sound).torque.SequenceEqual(finch.Resolve(sound).torque),"Repeated resolution cannot compound tune loss");
  var root=finch.FromLegacy(1,1,0);finch.Apply(root,finch.Find("induction_roots_1"));var sc=new FinchPowertrain(finch.Resolve(root));Check(!sc.definition.IsTurbo&&sc.definition.aspiration=="supercharged","SC uses immediate net curve, not turbo spool");Check(!WorkshopEffects.TurboAllowed(root,1,1,true),"SC cannot trigger turbo sound");root.sound="flame";root.exhaustStage=1;Check(WorkshopEffects.PopAllowed(root,4000,1,0,true)&&!WorkshopEffects.PopAllowed(root,4000,1,0,false),"Lift effect requires actual ground/load transition");
  var route=JsonUtility.FromJson<TrialDefinition>(Resources.Load<TextAsset>("FirstDocksideTrial").text);string folder=Path.GetFullPath("Verification/Workshop/profiles/"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);string path=Path.Combine(folder,"paid-v4.json");var store=new RaceProgressStore(path,route);for(int i=0;i<100;i++)store.Settle(Finish(route),out _);
  Reject(()=>Purchase(store,"induction_large_3"),"Cannot skip staged prerequisites");foreach(var id in new[]{"na_1","gearbox_1","induction_small_1","cooling_1","brakes_1","brakes_2","brakes_3","induction_roots_1"})Purchase(store,id);
  int credits=store.Profile.availableCredits;string request=Guid.NewGuid().ToString("N");store.PurchaseWorkshop(request,"induction_large_1",finch.Find("induction_large_1").price,out bool duplicate);Check(!duplicate,"New conversion charges once");int after=store.Profile.availableCredits;store.PurchaseWorkshop(request,"induction_large_1",finch.Find("induction_large_1").price,out duplicate);Check(duplicate&&store.Profile.availableCredits==after,"Committed request retry idempotent");Check(store.Profile.workshop.induction=="large"&&store.Profile.workshop.coolingStage==1,"Conversion replaces kit and retains paid matched cooling");Reject(()=>Purchase(store,"induction_large_1"),"No charge for same active kit");Purchase(store,"induction_small_1");Check(store.Profile.availableCredits==after-1900,"Returning to prior kit is a new disclosed full-kit payment");
  string paid=File.ReadAllText(path);var fault=new RaceProgressStore(path,route,()=>{throw new IOException("Injected failure");});Reject(()=>Purchase(fault,"intake_1"),"Atomic write failure rejected");Check(File.ReadAllText(path)==paid,"Failed payment changes no saved credits/build");Purchase(store,"intake_1");store=new RaceProgressStore(path,route);Check(store.Profile.workshop.intakeStage==1&&store.Profile.workshop.brakeStage==3,"Real staged hardware reloads");
  string legacyFile=Path.Combine(folder,"legacy-v3.json"),newFile=Path.Combine(folder,"migrated-v4.json");var historical=new RaceProgressStore(Path.Combine(folder,"historical.json"),route);for(int i=0;i<4;i++)historical.Settle(Finish(route),out _);foreach(var o in new[]{legacy.offer,legacy.gearboxOffer,legacy.turboOffer,legacy.intercoolerOffer})historical.PurchasePart(Guid.NewGuid().ToString("N"),o,o.price,out _);var v3=JsonUtility.FromJson<RaceProgress>(JsonUtility.ToJson(historical.Profile));v3.version=3;v3.workshop=null;File.WriteAllText(legacyFile,JsonUtility.ToJson(v3));string old=File.ReadAllText(legacyFile);var migrated=new RaceProgressStore(newFile,route,legacyFile:legacyFile);Check(migrated.Profile.version==4&&migrated.Profile.availableCredits==250&&migrated.Profile.spending.Count==4,"v3 migration preserves paid ledger and exact balance");Check(File.Exists(newFile)&&File.ReadAllText(legacyFile)==old,"Migration materializes v4 once; source byte-unchanged");File.WriteAllText(legacyFile,"corrupted later old save");Check(new RaceProgressStore(newFile,route,legacyFile:legacyFile).Profile.availableCredits==250,"v4 never reimports old save");
  string future=Path.Combine(folder,"future.json");File.WriteAllText(future,"{\"version\":5}");Reject(()=>new RaceProgressStore(future,route),"Unknown newer schema preserved/rejected");Check(File.ReadAllText(future)=="{\"version\":5}","Future file not overwritten");
  MeasureBrakes(finch);File.WriteAllLines("Verification/Workshop/rules.txt",lines);
 }catch(Exception e){lines.Add(e.ToString());File.WriteAllLines("Verification/Workshop/rules.txt",lines);throw;}}
 static void MeasureBrakes(WorkshopCatalog catalog){var old=Physics.simulationMode;Physics.simulationMode=SimulationMode.Script;try{EditorSceneManager.OpenScene("Assets/HarborValeGreybox/Driving/Scenes/Finch_HandlingTest.unity");foreach(var authored in UnityEngine.Object.FindObjectsByType<StarterCarSpecification>(FindObjectsSortMode.None))UnityEngine.Object.DestroyImmediate(authored.gameObject);var prefab=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/HarborValeGreybox/Expansion/Prefabs/AsterFinch.prefab");float prior=1000,priorTorque=0;foreach(int stage in new[]{0,1,2,3}){var g=(GameObject)PrefabUtility.InstantiatePrefab(prefab);g.transform.position=new Vector3(10,.35f,0);var car=g.AddComponent<FinchVehicle>();car.Initialize();car.externalInput=true;Physics.SyncTransforms();var build=new WorkshopBuild{brakeStage=stage};car.InstallPowertrain(catalog.Resolve(build));for(int i=0;i<160;i++){car.Tick(.02f);Physics.Simulate(.02f);}car.Body.linearVelocity=Vector3.forward*(100/3.6f);float start=car.Body.position.z;car.commandedPedal=-1;float peakTorque=0;for(int i=0;i<1500&&car.SpeedKph>2;i++){car.Tick(.02f);peakTorque=Mathf.Max(peakTorque,car.Wheels[0].brakeTorque);Physics.Simulate(.02f);}float distance=car.Body.position.z-start;Check(distance>0&&distance<=prior+.5f,"Measured Finch 100-2 km/h braking S"+stage+": "+distance.ToString("F2")+" m");Check(peakTorque>priorTorque,"Actual front brake torque S"+stage+": "+peakTorque.ToString("F1")+" Nm");priorTorque=peakTorque;prior=distance;UnityEngine.Object.DestroyImmediate(g);}}finally{Physics.simulationMode=old;}}
 public static void Release(){Run();HarborValeGreybox.Garage.Editor.GarageVerification.Run();HarborValeGreybox.Boost.Editor.BoostVerification.Run();HarborValeGreybox.Racing.Editor.TrialVerification.Run();HarborValeGreybox.Shifting.Editor.ShiftVerification.Run();HarborValeGreybox.Shifting.Editor.ShiftVerification.Build();}
}
}
